function l({registerIndicator:r,nulls:o}){r({id:"oa-medprice",name:"MEDPRICE: Median Price",category:"Price Core",placement:"onchart",inputs:[],plots:[{key:"medprice",type:"line",title:"MedPrice",style:{color:"#ff9800",lineWidth:2}}],calc(i){const t=new Array(i.length).fill(NaN);for(let e=0;e<i.length;e++){const n=Number(i[e].high),c=Number(i[e].low);!Number.isFinite(n)||!Number.isFinite(c)||(t[e]=(n+c)*.5)}return{medprice:o(t)}}})}export{l as default};
